insert into kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, source, year, exam_body, stem, options, correct_option, explanation, lifecycle_state, distractor_rationale) values
($q$chemistry_0267$q$, $q$Chemistry$q$, $q$Energy Changes$q$, $q$Heat of Combustion Calculations$q$, $q$Answer a real JAMB 2000 question on Heat of Combustion Calculations.$q$, $q$[{"conceptId": "6in5n9", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Gets the magnitude wrong by a factor of 10 and the sign wrong — likely a decimal-place slip in the mass-to-mole conversion combined with forgetting combustion is exothermic.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "Gets the correct magnitude (300) but the wrong sign — forgets that combustion releases heat, so ΔH must be negative, not positive.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "Correct sign but a factor-of-10 error in magnitude, most likely from misplacing a decimal point when dividing the total heat by the small number of moles (0.01 mol).", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$0.46g of ethanol when burned raised the temperature of 50 g water by 14.3 K. Calculate the heat of combustion of ethanol. [C=12, O=16, H=1, specific heat capacity of water = 4.2 Jg-1K-1]$q$, $q$[{"label": "A", "text": "+3 000 kJ mol-1", "isCorrect": false}, {"label": "B", "text": "+300 kJ mol-1", "isCorrect": false}, {"label": "C", "text": "-300 kJ mol-1", "isCorrect": true}, {"label": "D", "text": "-3 000 kJ mol-1", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Heat released: q = mcΔT = 50 × 4.2 × 14.3 ≈ 3003 J ≈ 3.0 kJ. Moles of ethanol burned: 0.46/46 = 0.01 mol (molar mass of C2H5OH = 24+6+16 = 46). Heat per mole = 3.0/0.01 = 300 kJ/mol. Combustion releases heat, so ΔH is negative: -300 kJ mol-1.$q$, $q$live$q$, $q$A: Gets the magnitude wrong by a factor of 10 and the sign wrong — likely a decimal-place slip in the mass-to-mole conversion combined with forgetting combustion is exothermic. B: Gets the correct magnitude (300) but the wrong sign — forgets that combustion releases heat, so ΔH must be negative, not positive. D: Correct sign but a factor-of-10 error in magnitude, most likely from misplacing a decimal point when dividing the total heat by the small number of moles (0.01 mol).$q$),
($q$chemistry_0268$q$, $q$Chemistry$q$, $q$Rates of Reaction$q$, $q$Rate of Reaction — Surface Area$q$, $q$Answer a real JAMB 2000 question on Rate of Reaction — Surface Area.$q$, $q$[{"conceptId": "5mzsr0", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "For an equal mass sample, powdering doesn't create more molecules of calcium carbonate — the same amount of substance is just broken into smaller pieces.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "Same error as 'more molecules' — the total number of atoms present depends on the mass, not on how finely it's divided.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Powdering a sample doesn't add mass to it — the mass stays the same, only the surface area exposed to the acid changes.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Powdered marble reacts with hydrochloric acid solution faster than the granular form because the powdered form has$q$, $q$[{"label": "A", "text": "more molecules", "isCorrect": false}, {"label": "B", "text": "more atoms", "isCorrect": false}, {"label": "C", "text": "larger surface area", "isCorrect": true}, {"label": "D", "text": "relatively larger mass", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$For the same total mass of marble, powdering it doesn't change how much marble you have — it changes how much of it is exposed to the acid at once. More exposed surface means more collisions happening simultaneously, which is why the reaction speeds up.$q$, $q$live$q$, $q$A: For an equal mass sample, powdering doesn't create more molecules of calcium carbonate — the same amount of substance is just broken into smaller pieces. B: Same error as 'more molecules' — the total number of atoms present depends on the mass, not on how finely it's divided. D: Powdering a sample doesn't add mass to it — the mass stays the same, only the surface area exposed to the acid changes.$q$),
($q$chemistry_0269$q$, $q$Chemistry$q$, $q$Chemical Equilibrium$q$, $q$Equilibrium Constant Expressions$q$, $q$Answer a real JAMB 2000 question on Equilibrium Constant Expressions.$q$, $q$[{"conceptId": "shtbq8", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Includes solids, which are specifically excluded from equilibrium expressions by convention since a pure solid's activity doesn't change.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "Includes both categories (liquid, solid) that are excluded from the expression, missing that it's the variable-concentration species (gas, dissolved) that actually belong.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "Half right (dissolved species do belong) but still includes solids, which don't.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$For a reaction in equilibrium, the species involved in the equilibrium constant expression are$q$, $q$[{"label": "A", "text": "gaseous and solid species", "isCorrect": false}, {"label": "B", "text": "liquid and solid species", "isCorrect": false}, {"label": "C", "text": "solid and dissolved species", "isCorrect": false}, {"label": "D", "text": "gaseous and dissolved species", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$By convention, pure solids and pure liquids are left out of an equilibrium constant expression entirely — their 'concentration' doesn't meaningfully change and is treated as a constant equal to 1. Only species whose concentration can actually vary — gases and dissolved (aqueous) species — appear in the Kc or Kp expression.$q$, $q$live$q$, $q$A: Includes solids, which are specifically excluded from equilibrium expressions by convention since a pure solid's activity doesn't change. B: Includes both categories (liquid, solid) that are excluded from the expression, missing that it's the variable-concentration species (gas, dissolved) that actually belong. C: Half right (dissolved species do belong) but still includes solids, which don't.$q$),
($q$chemistry_0270$q$, $q$Chemistry$q$, $q$Nature of Matter$q$, $q$Allotropy$q$, $q$Answer a real JAMB 2000 question on Allotropy.$q$, $q$[{"conceptId": "1e6r0v", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Confuses this with isomerism, which describes different compounds sharing a molecular formula — not the same single element appearing in different structural forms.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Amorphism describes a lack of ordered crystal structure, not the existence of multiple distinct forms of the same element.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Not a real term matching this definition — likely picked for sounding similar to 'allotropy' without the correct meaning.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$A phenomenon where an element exists in different forms in the same physical state is known as$q$, $q$[{"label": "A", "text": "isomerism", "isCorrect": false}, {"label": "B", "text": "amorphism", "isCorrect": false}, {"label": "C", "text": "allotropy", "isCorrect": true}, {"label": "D", "text": "isotropy", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Keep this apart from isomerism by what's varying: allotropy is the SAME element (like carbon) existing as different structural forms — diamond and graphite are both pure solid carbon, just arranged differently. Isomerism is about different COMPOUNDS sharing the same molecular formula, not the same element in different forms.$q$, $q$live$q$, $q$A: Confuses this with isomerism, which describes different compounds sharing a molecular formula — not the same single element appearing in different structural forms. B: Amorphism describes a lack of ordered crystal structure, not the existence of multiple distinct forms of the same element. D: Not a real term matching this definition — likely picked for sounding similar to 'allotropy' without the correct meaning.$q$),
($q$chemistry_0271$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Rubber Chemistry$q$, $q$Answer a real JAMB 2000 question on Rubber Chemistry.$q$, $q$[{"conceptId": "b3vqsm", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Chlorine isn't the crosslinking agent used in vulcanization — that's specifically sulphur, not a halogen.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Hydrogen peroxide is an oxidizer used in other industrial processes, not the classic vulcanizing agent for rubber.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Confuses the element (sulphur) with one of its acids (tetraoxosulphate VI, i.e. sulphuric acid) — it's the element itself that crosslinks the rubber, not the acid.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The substance often used for vulcanization of rubber is$q$, $q$[{"label": "A", "text": "chlorine", "isCorrect": false}, {"label": "B", "text": "hydrogen peroxide", "isCorrect": false}, {"label": "C", "text": "sulphur", "isCorrect": true}, {"label": "D", "text": "tetraoxosulphate (VI) acid", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Vulcanization is the process of heating natural rubber with sulphur, which forms crosslinking bridges between the polymer chains, making the rubber stronger and more elastic rather than sticky and weak.$q$, $q$live$q$, $q$A: Chlorine isn't the crosslinking agent used in vulcanization — that's specifically sulphur, not a halogen. B: Hydrogen peroxide is an oxidizer used in other industrial processes, not the classic vulcanizing agent for rubber. D: Confuses the element (sulphur) with one of its acids (tetraoxosulphate VI, i.e. sulphuric acid) — it's the element itself that crosslinks the rubber, not the acid.$q$),
($q$chemistry_0272$q$, $q$Chemistry$q$, $q$Environmental Pollution$q$, $q$Greenhouse Gases$q$, $q$Answer a real JAMB 2000 question on Greenhouse Gases.$q$, $q$[{"conceptId": "jiwfyk", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "CO2 is the single most commonly cited greenhouse gas — picking it as the exception gets the basic fact backwards.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "While SO3's main environmental concern is acid rain rather than warming specifically, it's still an atmospheric pollutant with radiative effects, unlike the genuinely inert-in-this-context H2.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Methane is one of the most potent greenhouse gases per molecule — picking it as 'not associated with warming' is a direct factual reversal.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$A gas that is not associated with global warming is$q$, $q$[{"label": "A", "text": "CO2", "isCorrect": false}, {"label": "B", "text": "SO3", "isCorrect": false}, {"label": "C", "text": "CH4", "isCorrect": false}, {"label": "D", "text": "H2", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$CO2 and CH4 are the two best-known greenhouse gases from the standard curriculum list. Hydrogen, by contrast, doesn't trap infrared radiation the way these gases do — it has no significant direct greenhouse effect, making it the clear odd one out here.$q$, $q$live$q$, $q$A: CO2 is the single most commonly cited greenhouse gas — picking it as the exception gets the basic fact backwards. B: While SO3's main environmental concern is acid rain rather than warming specifically, it's still an atmospheric pollutant with radiative effects, unlike the genuinely inert-in-this-context H2. C: Methane is one of the most potent greenhouse gases per molecule — picking it as 'not associated with warming' is a direct factual reversal.$q$),
($q$chemistry_0273$q$, $q$Chemistry$q$, $q$Air and Water$q$, $q$Dissolved Gases in Drinks$q$, $q$Answer a real JAMB 2000 question on Dissolved Gases in Drinks.$q$, $q$[{"conceptId": "fch4i1", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "Confuses CO2 (carbon IV oxide, the gas actually used for carbonation) with CO (carbon II oxide), which is a toxic gas that has no role in soft drinks at all.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Vague and non-specific — 'soda' isn't a defined chemical species responsible for the taste; the actual answer is the specific dissolved gas.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Glucose contributes sweetness in sugared drinks, but it's not what causes the characteristic fizzy/tangy taste — that's specifically the dissolved CO2.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The refreshing and characteristic taste of soda water and other soft drinks is as a result of the presence in them of$q$, $q$[{"label": "A", "text": "carbon (IV) oxide", "isCorrect": true}, {"label": "B", "text": "carbon (II) oxide", "isCorrect": false}, {"label": "C", "text": "soda", "isCorrect": false}, {"label": "D", "text": "glucose", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Carbonated drinks get their fizz and characteristic tang from dissolved carbon (IV) oxide (CO2), which forms a small amount of carbonic acid in solution — that mild acidity is exactly what gives soda water its distinctive taste.$q$, $q$live$q$, $q$B: Confuses CO2 (carbon IV oxide, the gas actually used for carbonation) with CO (carbon II oxide), which is a toxic gas that has no role in soft drinks at all. C: Vague and non-specific — 'soda' isn't a defined chemical species responsible for the taste; the actual answer is the specific dissolved gas. D: Glucose contributes sweetness in sugared drinks, but it's not what causes the characteristic fizzy/tangy taste — that's specifically the dissolved CO2.$q$),
($q$chemistry_0274$q$, $q$Chemistry$q$, $q$Nature of Matter$q$, $q$Adsorption$q$, $q$Answer a real JAMB 2000 question on Adsorption.$q$, $q$[{"conceptId": "5jews9", "weight": 1}]$q$::jsonb, 3, $q$recall$q$, 49, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "A plausible-sounding relative (also a form of activated carbon) but the specific fact being tested here points to animal charcoal, not the wood-derived form.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Carbon fibres are a structural/reinforcement material valued for strength, not an adsorption medium for gas purification.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Carbon black is a fine pigment and rubber-reinforcing filler, not the porous adsorbent form of carbon used in gas purification.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$A form of carbon used for absorbing poisonous gases and purification of noble gases is$q$, $q$[{"label": "A", "text": "wood charcoal", "isCorrect": false}, {"label": "B", "text": "animal charcoal", "isCorrect": true}, {"label": "C", "text": "carbon fibres", "isCorrect": false}, {"label": "D", "text": "carbon black", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Animal charcoal (bone char) has a historically well-documented use in gas purification and adsorption applications, valued for its high surface area at a level suited to this kind of purification role — this is the specific form the classic JAMB fact is pointing at, distinct from wood charcoal, carbon fibres (a structural material) or carbon black (a pigment/reinforcing filler).$q$, $q$live$q$, $q$A: A plausible-sounding relative (also a form of activated carbon) but the specific fact being tested here points to animal charcoal, not the wood-derived form. C: Carbon fibres are a structural/reinforcement material valued for strength, not an adsorption medium for gas purification. D: Carbon black is a fine pigment and rubber-reinforcing filler, not the porous adsorbent form of carbon used in gas purification.$q$),
($q$chemistry_0275$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Syngas$q$, $q$Answer a real JAMB 2000 question on Syngas.$q$, $q$[{"conceptId": "kt2ylw", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Lists methane and water, which are reactants used to produce syngas (via steam reforming), not the syngas mixture itself.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Keeps methane in the mixture instead of the actual defining components (CO and H2) — methane is what's reacted to make syngas, not a component of it.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Uses CO2 instead of CO — a one-oxygen difference that changes the whole identity of the gas mixture; syngas specifically contains carbon monoxide, not carbon dioxide.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Synthesis gas is a mixture of$q$, $q$[{"label": "A", "text": "CH4 and H2O", "isCorrect": false}, {"label": "B", "text": "CH4 and H2", "isCorrect": false}, {"label": "C", "text": "CO2 and H2", "isCorrect": false}, {"label": "D", "text": "CO and H2", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$'Syngas' is short for synthesis gas, and by definition it's a mixture of carbon monoxide and hydrogen — the starting material for industrial processes like methanol synthesis and the Fischer-Tropsch process for making fuels.$q$, $q$live$q$, $q$A: Lists methane and water, which are reactants used to produce syngas (via steam reforming), not the syngas mixture itself. B: Keeps methane in the mixture instead of the actual defining components (CO and H2) — methane is what's reacted to make syngas, not a component of it. C: Uses CO2 instead of CO — a one-oxygen difference that changes the whole identity of the gas mixture; syngas specifically contains carbon monoxide, not carbon dioxide.$q$),
($q$chemistry_0276$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$Flame Tests$q$, $q$Answer a real JAMB 2000 question on Flame Tests.$q$, $q$[{"conceptId": "865p59", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Blue isn't one of the standard alkali/alkaline-earth flame colours taught at this level — likely a guess rather than a recalled fact.", "misconceptionId": "guessed_no_reasoning"}, {"option": "B", "explanation": "Brick-red is calcium's flame colour, not potassium's — an easy mix-up between two commonly tested flame tests.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Golden-yellow is sodium's flame colour, not potassium's — a very common confusion since both are group 1 metals often tested together.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Potassium vapour burns with a$q$, $q$[{"label": "A", "text": "blue flame", "isCorrect": false}, {"label": "B", "text": "brick-red flame", "isCorrect": false}, {"label": "C", "text": "violet flame", "isCorrect": true}, {"label": "D", "text": "golden-yellow flame", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Potassium's flame test colour is lilac/violet — often described as a pale purple. Keep the common flame colours pinned down clearly: sodium is golden-yellow, calcium is brick-red, potassium is lilac/violet.$q$, $q$live$q$, $q$A: Blue isn't one of the standard alkali/alkaline-earth flame colours taught at this level — likely a guess rather than a recalled fact. B: Brick-red is calcium's flame colour, not potassium's — an easy mix-up between two commonly tested flame tests. D: Golden-yellow is sodium's flame colour, not potassium's — a very common confusion since both are group 1 metals often tested together.$q$),
($q$chemistry_0277$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$Reactivity and Corrosion Resistance$q$, $q$Answer a real JAMB 2000 question on Reactivity and Corrosion Resistance.$q$, $q$[{"conceptId": "5q74k0", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Metallic lustre is a real, true property of both metals, but it's an aesthetic feature, not the functional reason they were chosen for durable currency — that's their corrosion resistance.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Directly contradicts what makes them suitable for coinage — an easily oxidized metal would corrode quickly and be a poor choice for currency that needs to last.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "Confuses oxidation resistance with reduction — 'not easily reduced' isn't a meaningful or relevant property for why these metals suit coinage.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$A common characteristic of copper and silver in their usage as coinage metals is that they$q$, $q$[{"label": "A", "text": "have high metallic lustre", "isCorrect": false}, {"label": "B", "text": "are not easily oxidized", "isCorrect": true}, {"label": "C", "text": "are easily oxidized", "isCorrect": false}, {"label": "D", "text": "are not easily reduced", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$The property that actually makes a metal suitable for coinage is corrosion resistance — coins need to survive years of handling without rusting or tarnishing away. Copper and silver are both relatively unreactive ('noble') metals low on the reactivity series, which is exactly why they (along with gold) have been used for coinage throughout history.$q$, $q$live$q$, $q$A: Metallic lustre is a real, true property of both metals, but it's an aesthetic feature, not the functional reason they were chosen for durable currency — that's their corrosion resistance. C: Directly contradicts what makes them suitable for coinage — an easily oxidized metal would corrode quickly and be a poor choice for currency that needs to last. D: Confuses oxidation resistance with reduction — 'not easily reduced' isn't a meaningful or relevant property for why these metals suit coinage.$q$),
($q$chemistry_0278$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$Ores of Metals$q$, $q$Answer a real JAMB 2000 question on Ores of Metals.$q$, $q$[{"conceptId": "3b7g4n", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Zinc's common ore is zinc blende (sphalerite), not haematite.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Lead's common ore is galena, not haematite.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Copper's common ores include chalcopyrite and malachite, not haematite.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Haematite is an ore of$q$, $q$[{"label": "A", "text": "Zinc", "isCorrect": false}, {"label": "B", "text": "Lead", "isCorrect": false}, {"label": "C", "text": "Iron", "isCorrect": true}, {"label": "D", "text": "copper", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Haematite is iron (III) oxide, Fe2O3 — one of the most important iron ores, and a straightforward recall fact worth just knowing directly.$q$, $q$live$q$, $q$A: Zinc's common ore is zinc blende (sphalerite), not haematite. B: Lead's common ore is galena, not haematite. D: Copper's common ores include chalcopyrite and malachite, not haematite.$q$),
($q$chemistry_0279$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$Reactivity and Electrochemical Series$q$, $q$Answer a real JAMB 2000 question on Reactivity and Electrochemical Series.$q$, $q$[{"conceptId": "e6wz62", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Calcium, as a group 2 metal, is actually one of the more reactive metals here, not the least reactive.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Sodium is a group 1 metal and among the most reactive metals on the whole reactivity series — the opposite of 'least easily oxidized'.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Aluminium is more reactive than zinc on the standard reactivity series, even though its reactivity is sometimes masked by a protective oxide layer in everyday conditions.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The least easily oxidized of the metals below is$q$, $q$[{"label": "A", "text": "Ca", "isCorrect": false}, {"label": "B", "text": "Na", "isCorrect": false}, {"label": "C", "text": "Zn", "isCorrect": true}, {"label": "D", "text": "Al", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Place these on the reactivity series: Na and Ca are group 1 and 2 metals, both highly reactive and easily oxidized. Al is reactive too, though less so. Zinc sits lower still, making it the least easily oxidized (least reactive) of the four listed here.$q$, $q$live$q$, $q$A: Calcium, as a group 2 metal, is actually one of the more reactive metals here, not the least reactive. B: Sodium is a group 1 metal and among the most reactive metals on the whole reactivity series — the opposite of 'least easily oxidized'. D: Aluminium is more reactive than zinc on the standard reactivity series, even though its reactivity is sometimes masked by a protective oxide layer in everyday conditions.$q$),
($q$chemistry_0280$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Rubber Chemistry$q$, $q$Answer a real JAMB 2000 question on Rubber Chemistry.$q$, $q$[{"conceptId": "b3vqsm", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Alkynes is a whole class of compounds (containing a triple bond), not the specific monomer that makes up natural rubber.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "n-propane is a simple 3-carbon alkane, structurally unrelated to the branched diene monomer that builds up rubber.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Neoprene is a synthetic rubber made from a different monomer (chloroprene) — confuses the natural rubber monomer with a related but distinct synthetic material.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The repeating unit in natural rubber is$q$, $q$[{"label": "A", "text": "alkynes", "isCorrect": false}, {"label": "B", "text": "isoprene", "isCorrect": true}, {"label": "C", "text": "n-propane", "isCorrect": false}, {"label": "D", "text": "neoprene", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Natural rubber is a polymer built from repeating isoprene units (2-methylbuta-1,3-diene) — this monomer, linked together thousands of times, is exactly what gives rubber its elastic, coiled polymer structure.$q$, $q$live$q$, $q$A: Alkynes is a whole class of compounds (containing a triple bond), not the specific monomer that makes up natural rubber. C: n-propane is a simple 3-carbon alkane, structurally unrelated to the branched diene monomer that builds up rubber. D: Neoprene is a synthetic rubber made from a different monomer (chloroprene) — confuses the natural rubber monomer with a related but distinct synthetic material.$q$),
($q$chemistry_0281$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Tests for Unsaturation$q$, $q$Answer a real JAMB 2000 question on Tests for Unsaturation.$q$, $q$[{"conceptId": "xd7de2", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Swaps in silver bromide, which is a photographic/precipitation reagent with no role in testing for unsaturation, in place of bromine water.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Same substitution error — silver bromide isn't a decolourization test for unsaturation, regardless of which other reagent it's paired with.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Gets both reagents conceptually right in kind but specifies 'alkaline' instead of 'acidified' potassium tetraoxomanganate (VII) — the standard classroom test uses the acidified form.", "misconceptionId": "memorized_not_understood"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Unsaturated organic compounds are identified by decolourization of$q$, $q$[{"label": "A", "text": "silver bromide and potassium tetraoxomanganate (VII) solution", "isCorrect": false}, {"label": "B", "text": "bromine water and acidified potassium tetraoxomanganate (VII) solution", "isCorrect": true}, {"label": "C", "text": "silver bromide solution and bromine water", "isCorrect": false}, {"label": "D", "text": "bromine water and alkaline potassium tetraoxomanganate (VII) solution", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Two standard tests confirm unsaturation (a C=C or C≡C bond): bromine water decolourises via an addition reaction across the double/triple bond, and acidified (not alkaline) potassium tetraoxomanganate (VII) also decolourises by oxidizing across the same bond. The 'acidified' condition matters specifically — that's the classic test as usually taught.$q$, $q$live$q$, $q$A: Swaps in silver bromide, which is a photographic/precipitation reagent with no role in testing for unsaturation, in place of bromine water. C: Same substitution error — silver bromide isn't a decolourization test for unsaturation, regardless of which other reagent it's paired with. D: Gets both reagents conceptually right in kind but specifies 'alkaline' instead of 'acidified' potassium tetraoxomanganate (VII) — the standard classroom test uses the acidified form.$q$),
($q$chemistry_0282$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Extraction of a Water Molecule Between Alcohols$q$, $q$Answer a real JAMB 2000 question on Extraction of a Water Molecule Between Alcohols.$q$, $q$[{"conceptId": "kflkb0", "weight": 1}]$q$::jsonb, 4, $q$application$q$, 81, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "Keeps the correct lower temperature for ether formation but pairs it with excess acid, which actually favours the competing intramolecular (alkene-forming) pathway instead.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Describes the conditions for the alkene-forming (intramolecular) dehydration instead — the two dehydration pathways and their conditions have been swapped.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Mixes the correct acid condition (less acid, favouring ether formation) with the wrong temperature (higher, which actually favours alkene formation) — a partial mix-up of the two competing pathways.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The conditions necessary for the extraction of a water molecule from two molecules of ethanol are$q$, $q$[{"label": "A", "text": "less acid and a lower temperature", "isCorrect": true}, {"label": "B", "text": "excess acid and a lower temperature", "isCorrect": false}, {"label": "C", "text": "excess acid and a higher temperature", "isCorrect": false}, {"label": "D", "text": "less acid and a higher temperature", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Removing water between two separate ethanol molecules is intermolecular dehydration, which forms an ether (diethyl ether). This is the low-temperature pathway (around 140°C), favoured when acid is relatively less concentrated so alcohol is effectively in excess. The alternative — one ethanol molecule losing water from within itself to form an alkene — needs excess concentrated acid and higher temperature (around 170°C). Mixing up these two conditions is the classic trap in this topic.$q$, $q$live$q$, $q$B: Keeps the correct lower temperature for ether formation but pairs it with excess acid, which actually favours the competing intramolecular (alkene-forming) pathway instead. C: Describes the conditions for the alkene-forming (intramolecular) dehydration instead — the two dehydration pathways and their conditions have been swapped. D: Mixes the correct acid condition (less acid, favouring ether formation) with the wrong temperature (higher, which actually favours alkene formation) — a partial mix-up of the two competing pathways.$q$),
($q$chemistry_0283$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Uses of Chlorinated Solvents$q$, $q$Answer a real JAMB 2000 question on Uses of Chlorinated Solvents.$q$, $q$[{"conceptId": "yklr2g", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "Chloromethane is mainly known as a reactive intermediate in stepwise chlorination, not as a degreasing solvent.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Trichloromethane (chloroform) is associated with anaesthesia, not industrial degreasing.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Dichloromethane is a common paint-stripping and extraction solvent, but it's not the specific compound historically named for industrial degreasing in this context.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The chlorinated alkane often used industrially to remove grease is$q$, $q$[{"label": "A", "text": "tetrachloromethane", "isCorrect": true}, {"label": "B", "text": "chloromethane", "isCorrect": false}, {"label": "C", "text": "trichloromethane", "isCorrect": false}, {"label": "D", "text": "dichloromethane", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Tetrachloromethane (carbon tetrachloride, CCl4) was historically the standard industrial degreasing solvent, valued for dissolving oils and greases effectively (though it's now heavily restricted due to toxicity — this is the classic exam fact, describing its historical industrial role).$q$, $q$live$q$, $q$B: Chloromethane is mainly known as a reactive intermediate in stepwise chlorination, not as a degreasing solvent. C: Trichloromethane (chloroform) is associated with anaesthesia, not industrial degreasing. D: Dichloromethane is a common paint-stripping and extraction solvent, but it's not the specific compound historically named for industrial degreasing in this context.$q$),
($q$chemistry_0284$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Industrial Production of Acetylene$q$, $q$Answer a real JAMB 2000 question on Industrial Production of Acetylene.$q$, $q$[{"conceptId": "znym3c", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "Ethane is a fully saturated alkane — but calcium carbide contains a carbon-carbon triple bond (it's literally 'carbide' because of the C≡C unit), which carries through to give a triple-bonded product, not a saturated one.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Ethene has a double bond, but the carbide ion's structure (with its own triple bond) leads to ethyne, not the intermediate unsaturation level of ethene.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Ethanal is an aldehyde and has no direct relationship to the simple hydrolysis of calcium carbide.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The reaction of carbide with water gives$q$, $q$[{"label": "A", "text": "ethyne", "isCorrect": true}, {"label": "B", "text": "ethane", "isCorrect": false}, {"label": "C", "text": "ethene", "isCorrect": false}, {"label": "D", "text": "ethanal", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Calcium carbide (CaC2) reacting with water is the classic industrial route to acetylene: CaC2 + 2H2O → C2H2 + Ca(OH)2. This is also literally how old carbide miners' lamps generated their fuel gas on demand.$q$, $q$live$q$, $q$B: Ethane is a fully saturated alkane — but calcium carbide contains a carbon-carbon triple bond (it's literally 'carbide' because of the C≡C unit), which carries through to give a triple-bonded product, not a saturated one. C: Ethene has a double bond, but the carbide ion's structure (with its own triple bond) leads to ethyne, not the intermediate unsaturation level of ethene. D: Ethanal is an aldehyde and has no direct relationship to the simple hydrolysis of calcium carbide.$q$),
($q$chemistry_0285$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Functional Group Identification — Esters$q$, $q$Answer a real JAMB 2000 question on Functional Group Identification — Esters.$q$, $q$[{"conceptId": "kmmznm", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Sees the C-O-C linkage and calls it an ether, but misses the carbonyl group (C=O) directly attached — an ether has no carbonyl at all.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Correctly spots the carbonyl group but misreads the structure — an alkanal's carbonyl carbon is bonded to a hydrogen at the chain end, not to another oxygen linking to a second carbon chain.", "misconceptionId": "misread_graph"}, {"option": "D", "explanation": "Confuses this structure with an alcohol (-OH group), which isn't present here at all — this molecule has a carbonyl and an ester oxygen bridge instead.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$CH3-CH2-C(=O)-O-CH2-CH3. The compound above is an$q$, $q$[{"label": "A", "text": "ether", "isCorrect": false}, {"label": "B", "text": "ester", "isCorrect": true}, {"label": "C", "text": "alkanal", "isCorrect": false}, {"label": "D", "text": "alkanol", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$The C(=O)-O- linkage — a carbonyl carbon directly bonded to a single-bonded oxygen that connects to another carbon chain — is the defining ester functional group. An ether has no carbonyl at all (just C-O-C), an alkanal's carbonyl is at the end of the chain with an H attached, and an alkanol has an -OH group, none of which matches this structure.$q$, $q$live$q$, $q$A: Sees the C-O-C linkage and calls it an ether, but misses the carbonyl group (C=O) directly attached — an ether has no carbonyl at all. C: Correctly spots the carbonyl group but misreads the structure — an alkanal's carbonyl carbon is bonded to a hydrogen at the chain end, not to another oxygen linking to a second carbon chain. D: Confuses this structure with an alcohol (-OH group), which isn't present here at all — this molecule has a carbonyl and an ester oxygen bridge instead.$q$),
($q$chemistry_0286$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Oxidation of Alcohols$q$, $q$Answer a real JAMB 2000 question on Oxidation of Alcohols.$q$, $q$[{"conceptId": "4f68ue", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Primary alcohols do oxidize, but they go on to form aldehydes (and then carboxylic acids), not ketones — they have a hydrogen left over that secondary alcohols don't.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Tertiary alcohols have no hydrogen on the carbon bearing the -OH group, so they resist oxidation under normal conditions entirely — they can't form ketones or anything else this way.", "misconceptionId": "missing_prerequisite"}, {"option": "D", "explanation": "An alkanoic acid is already a fully oxidized end-product of a primary alcohol, not a starting material that gets oxidized further into a ketone.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Alkanones are generally obtained by the oxidation of$q$, $q$[{"label": "A", "text": "primary alkanols", "isCorrect": false}, {"label": "B", "text": "secondary alkanols", "isCorrect": true}, {"label": "C", "text": "tertiary alkanols", "isCorrect": false}, {"label": "D", "text": "alkanoic acid", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Where oxidation stops depends on how many hydrogens are on the carbon bearing the -OH group. A secondary alcohol has exactly one hydrogen there, and oxidizing it removes that hydrogen to form a ketone (alkanone) — with no further hydrogen available, oxidation stops there. Primary alcohols have two such hydrogens and oxidize further, through an aldehyde and on to a carboxylic acid. Tertiary alcohols have no hydrogen on that carbon at all and can't be oxidized this way under normal conditions.$q$, $q$live$q$, $q$A: Primary alcohols do oxidize, but they go on to form aldehydes (and then carboxylic acids), not ketones — they have a hydrogen left over that secondary alcohols don't. C: Tertiary alcohols have no hydrogen on the carbon bearing the -OH group, so they resist oxidation under normal conditions entirely — they can't form ketones or anything else this way. D: An alkanoic acid is already a fully oxidized end-product of a primary alcohol, not a starting material that gets oxidized further into a ketone.$q$),
($q$chemistry_0287$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Carbohydrates — Identification and Formula$q$, $q$Answer a real JAMB 2000 question on Carbohydrates — Identification and Formula.$q$, $q$[{"conceptId": "d1sp6r", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Describes maltose's composition (two glucose units), not sucrose's.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Not a naturally common disaccharide pairing at all — fructose typically appears paired with glucose, not with itself.", "misconceptionId": "guessed_no_reasoning"}, {"option": "D", "explanation": "Describes lactose's composition (galactose+glucose), not sucrose's — an easy mix-up between the common milk sugar and table sugar.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Sucrose is made up of$q$, $q$[{"label": "A", "text": "glucose and glucose", "isCorrect": false}, {"label": "B", "text": "glucose and fructose", "isCorrect": true}, {"label": "C", "text": "fructose and fructose", "isCorrect": false}, {"label": "D", "text": "galactose and glucose", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Sucrose (table sugar) is a disaccharide of one glucose unit and one fructose unit joined together. Keeping the common disaccharides straight: maltose is glucose+glucose, lactose is glucose+galactose, and sucrose is glucose+fructose.$q$, $q$live$q$, $q$A: Describes maltose's composition (two glucose units), not sucrose's. C: Not a naturally common disaccharide pairing at all — fructose typically appears paired with glucose, not with itself. D: Describes lactose's composition (galactose+glucose), not sucrose's — an easy mix-up between the common milk sugar and table sugar.$q$);
